=<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Emissão de documentos</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Roboto:wght@500&display=swap">
<style>
  body { margin: 0; min-height: 100vh; display: grid; place-items: center; font-family: system-ui, sans-serif;
         background: #f2f5f5; color: #1f2a2b; }
  main { width: min(360px, calc(100% - 32px)); box-sizing: border-box; background: #fff; border-radius: 16px;
         padding: 32px 24px; box-shadow: 0 1px 3px rgba(0,0,0,.08); border-top: 4px solid {{ $json.cor }}; text-align: center; }
  img { max-width: 180px; height: auto; margin-bottom: 8px; }
  h1 { margin: 0 0 8px; font-size: 1.2rem; color: {{ $json.cor }}; }
  p { margin: 0 0 24px; color: #5f6f70; font-size: .95rem; }
  .aviso { color: #b3261e; background: #fdecea; border-radius: 8px; padding: 10px 12px; font-size: .9rem; }
  a.google { display: inline-flex; align-items: center; gap: 10px; height: 40px; padding: 0 12px;
             border: 1px solid #747775; border-radius: 20px; background: #fff; color: #1f1f1f;
             font: 500 14px Roboto, arial, sans-serif; text-decoration: none; }
  a.google:hover { background: #f8f9fa; }
  small { display: block; margin-top: 24px; color: #5f6f70; }
</style>
</head>
<body>
<main>
  {{ $json.logo }}
  <h1>Emissão de documentos</h1>
  <p>Entre com a conta Google {{ $json.de_quem }} para emitir certificados e declarações.</p>
  {{ $json.aviso }}
  <a class="google" href="{{ $json.google }}"><svg viewBox="0 0 48 48" width="20" height="20" aria-hidden="true"><path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/><path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/><path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/><path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/></svg><span>Fazer login com o Google</span></a>
  <small>Acesso restrito à equipe.</small>
</main>
</body>
</html>
